const cases={
threads:{name:'LIGHT IN THREADS 2.0',year:'27–28 June 2026',type:'Event management / Projenius',intro:'Illuminate the Unseen. Two days of faith, fashion and creative expression in Abuja.',challengeTitle:'THE EVENT',challenge:'Organised by the Fashion Connect and Creative Connect groups of Supernatural Life Church (SLC), the event brought industry learning, designer collections and live performance into a shared programme.',workTitle:'THE PROGRAMME',work:['27 June: a creative and fashion industry seminar, with conversations, learning and connection.','28 June: a runway exhibition of faith-based and modest designer collections, alongside creative performances.','Runway venue: National Centre for Women’s Development, Tafawa Balewa Way, Abuja.'],outcomeTitle:'MY ROLE',outcome:'I own Projenius and work in event management through the company, alongside my brand and content strategy practice.',note:'Event information and photography come from the supplied Projenius portfolio. Detailed individual production responsibilities and attendance figures are not specified.',image:'light-in-threads-panel.jpg',imageAlt:'Panel conversation at LIGHT IN THREADS 2.0',secondImage:'light-in-threads-runway.jpg',secondAlt:'Runway look featuring colourful thread spools and orange sleeves'},
blvck:{name:'Project BLVCK',year:'27 September 2025',type:'Event management / Projenius',intro:'A Pan-African exhibition exploring identity, migration and the relationships that sustain communities.',challengeTitle:'THE EXHIBITION',challenge:'The exhibition programme announced Orisun Art Gallery, Tropic Galleria, Abuja as its venue. Richardson Ojeka convened the project, with Adebayo Ebenezer Seun as curator.',workTitle:'IN THE PROGRAMME',work:['Dog in the City: an exploration of identity, dignity and the uncertainty of migration.','The African Family: a reflection on kinship, community and shared heritage.','A platform for African artistic expression, cultural conversation and belonging.'],outcomeTitle:'MY ROLE',outcome:'I own Projenius and work in event management through the company, alongside my brand and content strategy practice.',note:'The date and venue follow the supplied exhibition programme. The image is exhibition artwork; it does not document the installation. Detailed individual responsibilities and delivery outcomes are not specified.',image:'project-blvck-artwork.png',imageAlt:'Dog in the City, a Project BLVCK exhibition artwork'},

remsleep:{name:'RemSleep',year:'2026',type:'Brand & content strategy',intro:'A premium-accessible sleep brand needed a clear direction it could keep.',challenge:'Build a brand around quality and comfort without treating luxury as effortless or out of reach. The work needed to guide everyday decisions as well as the initial positioning.',work:['Researched the category, competitors and target audience.','Developed positioning, voice principles and content territories.','Created editorial guidance and a reusable operations bible, including AI prompts and workflow support.'],outcome:'The brand owner implemented fixed brand directives in place of changing “vibes and ideals.” The result was a shared reference for applying the strategy consistently.',note:'The documented outcome is implementation of the brand directives. No sales or conversion lift is claimed.'},
ovalay:{name:'Ovalay',year:'2023',type:'Market re-entry & campaign strategy',intro:'A paused brand needed a reason to return, and an audience needed a reason to pay attention.',challenge:'Help Ovalay re-enter the market after a hiatus with a refreshed direction that went beyond a relaunch announcement.',work:['Refreshed positioning and marketing direction, and defined product target markets.','Developed partnership outlines and a content calendar around audience interest and lead generation.','Created “12 Days of Design Therapy,” a daily December Twitter Live speaker series with themed conversations.'],outcome:'A recurring format gave the brand a way to invite people back. The portfolio records two public post snapshots: 807 views, 5 likes and 5 reposts on 22 December; 1.4K views, 18 likes and 8 reposts on 24 December.',note:'These are individual post snapshots, not campaign totals, attendance figures or evidence of a before-and-after engagement lift.'},
bechi:{name:'Bechi’s Stitches',year:'2021',type:'Naming, positioning & brand presence',intro:'A neighbourhood tailoring business had the potential to become something bigger.',challenge:'Give the business an identity that reflected the quality of its work and left room for growth beyond its existing neighbourhood service.',work:['Helped name and reposition the business as Bechi’s Stitches.','Shaped its identity and curated its logo direction.','Developed a proof-led social presence that put the work at the centre of the story.'],outcome:'The brand foundation gave the business a clearer presence. It later moved into ready-to-wear and rebranded as Styled by Beulah.',note:'Victoria’s contribution covered the Bechi’s Stitches brand foundation. The later ready-to-wear direction is part of the business’s subsequent story.'},
aiesec:{name:'AIESEC',year:'2022–2025',type:'Campaign & content strategy',intro:'One central idea. A local expression that feels familiar.',challenge:'Help campaigns travel across contexts without losing their central idea or sounding detached from the people receiving them.',work:['Collaborated with AIESEC entities, including the UAE and Albania.','Adapted campaign examples and messaging for local audiences.','Kept the central idea and brand intent consistent across those adaptations.'],outcome:'The work focused on balancing shared campaign direction with examples and language people could recognise in their own context.',note:'“Rent A Dress,” included in the full portfolio, is a proposed concept for interview clothing access. It is not presented as an executed campaign.'},
hawksworth:{name:'Hawksworth Advisors',year:'January 2024',type:'Research, digital direction & content',intro:'Research becomes valuable when it helps people make a clearer decision.',challenge:'Understand how a business group appeared online and translate gaps in trust and visibility into useful recommendations.',work:['Researched businesses, sectors and markets for advisory assignments, expressions of interest and client proposals.','Audited the group’s digital presence and proposed web and social direction.','Wrote UX copy for five subsidiary websites, alongside newsletters and a content map.'],outcome:'The research informed concrete web and content recommendations, with copy and editorial direction that the businesses could use.',note:'Five subsidiary websites describes the scope of copywriting. No traffic or commercial outcome is claimed.'},
tony:{name:'Tony & Co',year:'2025',type:'Executive support & brand operations',intro:'Good work needs clear communication at every handoff.',challenge:'Keep day-to-day brand work moving between clients, leadership and staff while supporting executive priorities.',work:['Coordinated client, leadership and team communication.','Aligned briefs, decisions, updates and handoffs.','Supported coordination around brand and founder-facing client work, including 404 Fund.'],outcome:'The role connected executive support with everyday brand operations, helping the people involved stay aligned on the work and the decisions it needed.',note:'This case describes an operations and coordination contribution, rather than sole ownership of client brand strategy.'}
};
const dialog=document.querySelector('#case-dialog');let currentCase='remsleep';let lastTrigger;
function renderCase(key){currentCase=key;const c=cases[key];document.querySelector('#case-body').innerHTML=`<h2 id="case-title">${c.name}</h2><p class="case-intro">${c.intro}</p>${c.image?`<img class="case-event-image" src="assets/${c.image}" alt="${c.imageAlt}">`:""}<dl class="case-facts"><div><dt>WHEN</dt><dd>${c.year}</dd></div><div><dt>FOCUS</dt><dd>${c.type}</dd></div></dl><section class="case-section"><h3>${c.challengeTitle||"THE CHALLENGE"}</h3><p>${c.challenge}</p></section><section class="case-section"><h3>${c.workTitle||"MY CONTRIBUTION"}</h3><ul>${c.work.map(w=>`<li>${w}</li>`).join('')}</ul></section><section class="case-section"><h3>${c.outcomeTitle||"WHAT FOLLOWED"}</h3><p>${c.outcome}</p></section>${c.secondImage?`<img class="case-event-image secondary" src="assets/${c.secondImage}" alt="${c.secondAlt}" loading="lazy">`:""}<p class="case-note">${c.note}</p>`;dialog.scrollTop=0;}
document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>{lastTrigger=b;renderCase(b.dataset.case);dialog.showModal();document.body.classList.add('modal-open');}));
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus({preventScroll:true});});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelector('#next-case').addEventListener('click',()=>{const keys=Object.keys(cases);renderCase(keys[(keys.indexOf(currentCase)+1)%keys.length]);document.querySelector('#close-dialog').focus({preventScroll:true});});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('.project').forEach(p=>p.hidden=button.dataset.filter!=='all'&&!p.dataset.category.split(' ').includes(button.dataset.filter));}));
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('yagazieemole@gmail.com');status.textContent='Email address copied.';}catch{status.textContent='Email: yagazieemole@gmail.com';}});
